'use strict';
(() => {
  const C = window.COURSE;
  const $ = (s, root = document) => root.querySelector(s);
  const $$ = (s, root = document) => [...root.querySelectorAll(s)];
  const esc = s => String(s ?? '').replace(/\bWT\s*11505\b/gi, '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const icon = name => { const paths = {home:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',book:'<path d="M12 5c-4-3-7-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-2-1-5-2-9 1Z"/><path d="M12 5v15"/>',code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6m-3-15-2 18"/>',lab:'<path d="M9 3h6m-5 0v7L4 20a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1l-6-10V3M7 15h10"/>',files:'<path d="M3 7h7l2-3h8a1 1 0 0 1 1 1v14a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V7Zm0 3h18"/>',self:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-3a8 8 0 0 1 16 0v3"/>',check:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="m8 12 3 3 5-6"/>',star:'<path d="m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 10v7m0-11v1"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>'}; return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name] || paths.book}</svg>`; };
  const NAV = [['home','Учебный план','home',''],['calendar','Календарный план','check',''],['syllabus','Syllabus','book',''],['course','Текст лекций','book',''],['practice','Задания для практики','code',''],['library','Библиотека материалов','files',''],['tk','Задания для ТК','check',''],['pk','Вопросы для ПК','info',''],['ik','Тесты для ИК','check','']];
  const KINDS = {lecture:'Лекция',practice:'Практика из архива',lab:'Лабораторная',slides:'PDF-лекция',srs:'Самостоятельная',exam:'Экзаменационный архив'};
  const ALL_ITEMS = [...C.lectures,...C.practices,...C.srs,...C.labs,...C.docs];
  const validKeys = new Set(ALL_ITEMS.map(x => x.code || x.id));
  let state = {done:[],saved:[],checks:{},last:'M1',theme:'dark'};
  try { const saved = JSON.parse(localStorage.getItem('wt11505-studio-v1') || '{}'); if(saved && typeof saved === 'object') state = {...state,...saved}; } catch {}
  state.done = Array.isArray(state.done) ? state.done.filter(k => validKeys.has(k)) : [];
  state.saved = Array.isArray(state.saved) ? state.saved.filter(k => validKeys.has(k)) : [];
  state.checks = state.checks && typeof state.checks === 'object' && !Array.isArray(state.checks) ? state.checks : {};
  if(!C.lectures.some(x=>x.code===state.last)) state.last='M1';
  const menuMedia=matchMedia('(max-width: 920px)');
  function syncMenu(){const closed=menuMedia.matches&&!document.body.classList.contains('menu-open');$('#sidebar').inert=closed;$('#sidebar').setAttribute('aria-hidden',String(closed));}
  menuMedia.addEventListener('change',syncMenu);syncMenu();
  let storageWarningShown = false;
  function save() { try { localStorage.setItem('wt11505-studio-v1',JSON.stringify(state)); } catch { if(!storageWarningShown){toast('Браузер не разрешил сохранение. Прогресс доступен до закрытия страницы.');storageWarningShown=true;} } updateProgress(); }
  function applyTheme(){document.body.classList.toggle('light',state.theme==='light');$('#themeToggle').setAttribute('aria-label','Переключить цветовую тему');}
  applyTheme();
  let toastTimer;
  function toast(message){if(window.portalUI?.notify(message))return;$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
  const isDone = key => state.done.includes(key);
  const isSaved = key => state.saved.includes(key);
  const routeFor = x => x.id ? `#material/${x.id}` : `#${x.code.startsWith('M')?'lesson':x.code.startsWith('A')?'task':x.code.startsWith('S')?'selfstudy':'lab'}/${x.code}`;
  const size = n => n>=1048576?`${(n/1048576).toFixed(1)} МБ`:`${Math.ceil(n/1024)} КБ`;
  const docsFor = code => C.docs.filter(d=>d.refs.includes(code));
  const tag = (text,cls='') => `<span class="tag ${cls}">${esc(text)}</span>`;
  const btn = (label,href,cls='') => `<a class="button ${cls}" href="${esc(href)}">${label}</a>`;
  const bookmark = key => `<button class="icon-button bookmark ${isSaved(key)?'active':''}" data-save="${esc(key)}" aria-label="${isSaved(key)?'Убрать из сохранённого':'Сохранить материал'}" aria-pressed="${isSaved(key)}" title="${isSaved(key)?'Убрать из сохранённого':'Сохранить'}">${icon('star')}</button>`;
  const head = (title,subtitle,eyebrow,number='') => `<div class="page-head"><div><div class="eyebrow"><span class="slash">/</span> ${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${number?`<span class="number-stamp" aria-hidden="true">${number}</span>`:''}</div>`;
  const callout = (title,text,warn=false) => `<div class="callout ${warn?'warn':''}"><strong>${esc(title)}</strong>${esc(text)}</div>`;
  const codeBlock = (lang,code) => `<div class="code-block"><div class="code-head"><span>${esc(lang.toUpperCase())}</span><button class="copy-button" data-copy>Копировать ⧉</button></div><pre><code>${esc(code)}</code></pre></div>`;
  const empty = (title,text,href='#course',label='Открыть лекции') => `<div class="empty"><strong>${esc(title)}</strong>${esc(text)}<div>${btn(esc(label),href,'secondary')}</div></div>`;
  const qa = rows => rows.map(x=>`<details class="question"><summary>${esc(x.question)}</summary><p>${esc(x.answer)}</p></details>`).join('');
  function updateProgress(){ /* Saved materials remain local; the portal has no course completion score. */ }
  function nav(section){$('#nav').innerHTML=NAV.map(([key,label,symbol,count],i)=>`<a href="#${key}" class="${key===section?'active':''}" ${key===section?'aria-current="page"':''}><span class="nav-number">${String(i+1).padStart(2,'0')}</span><span>${label}</span><span class="nav-arrow">↗</span></a>`).join('');$('#crumb').textContent=NAV.find(x=>x[0]===section)?.[1]||({labs:'Лабораторные работы',self:'Самостоятельная работа',assessment:'Баллы и допуск',saved:'Избранные материалы',playground:'Примеры кода',about:'О дисциплине'}[section]||'Материал');}

  function home(){return `<section class="discipline-hero"><div class="eyebrow"><span class="status-dot"></span> УЧЕБНЫЙ ПЛАН <span class="slash">/</span> TIFT UNIVERSITY</div><div class="hero-layout"><div class="hero-copy"><div class="hero-overline"><span>05 / СЕМЕСТР</span><span>2026 — 2027</span></div><h1>Веб<span class="title-line">технологии<span class="title-dot">.</span></span></h1><p class="discipline-lead">Твоя дисциплина. Все материалы.<br>Открой нужное — и продолжай разбираться.</p><div class="hero-actions">${btn('Найти материалы <span>↗</span>','#course')}${btn('Учебный план ↓','sources/study-plan.docx','secondary')}</div><div class="hero-footnote"><span class="status-dot"></span> Лекции, задания и подготовка к контролю</div></div><div class="web-scene" aria-hidden="true"><div class="scene-orbit orbit-one"></div><div class="scene-orbit orbit-two"></div><span class="scene-spark spark-one">✳</span><span class="scene-spark spark-two">+</span><div class="scene-browser"><div class="scene-bar"><i></i><i></i><i></i><span>your.next.idea</span><b>↗</b></div><div class="scene-content"><span class="scene-label">FROM CODE TO SOMETHING REAL</span><div class="scene-glyph">&lt;<span>/</span>&gt;</div><div class="scene-code"><span>const</span> future = <i>create</i>();<br><b>future</b>.start(<span>you</span>);</div><div class="scene-line"><i></i><i></i><i></i></div></div></div><span class="scene-chip chip-html">HTML <b>5</b></span><span class="scene-chip chip-css">{ CSS }</span><span class="scene-chip chip-js">JS <i>↗</i></span><span class="scene-caption">ИЗУЧАЙ. СОЗДАВАЙ. РАЗБИРАЙСЯ.</span></div></div></section>
    <section class="plan-stats" aria-label="Часы дисциплины">${[['44','Лекции','20 тем'],['46','Практические занятия','15 тем'],['90','Самостоятельная работа','21 тема'],['180','Всего часов','5 ECTS по программе']].map(([n,t,sub])=>`<div><strong>${n}<small> ч</small></strong><p>${t}</p><span>${sub}</span></div>`).join('')}</section>
    <section class="portal-section"><div class="section-head"><div><h2>Найти нужный материал</h2><p>Выбери раздел — посмотри содержание или скачай файл.</p></div><button class="button small secondary" data-search-open>Поиск по материалам ⌕</button></div><div class="portal-shortcuts">${[['course','book','Тексты лекций','20 тем с материалами по программе'],['practice','code','Практические задания','Условия, порядок работы и файлы'],['library','files','Библиотека материалов','65 исходных документов'],['tk','check','ТК → ПК → ИК','Задания, вопросы и условия контроля']].map(([url,ic,t,desc])=>`<a href="#${url}" class="portal-shortcut"><span class="shortcut-icon">${icon(ic)}</span><h3>${t}</h3><p>${desc}</p><b>↗</b></a>`).join('')}</div></section>
    <section class="portal-section"><div class="section-head"><div><h2>Учебный план дисциплины</h2><p>Объём и виды работы по учебной программе.</p></div>${btn('Syllabus ↗','#syllabus','small secondary')}</div><div class="table-wrap"><table class="study-table"><thead><tr><th>Вид учебной работы</th><th>Темы</th><th>Часы</th><th>Материалы</th></tr></thead><tbody><tr><td>Лекционные занятия</td><td>M1–M20</td><td>44</td><td><a href="#course">Открыть лекции ↗</a></td></tr><tr><td>Практические занятия</td><td>A1–A15</td><td>46</td><td><a href="#practice">Открыть задания ↗</a></td></tr><tr><td>Самостоятельная работа</td><td>S1–S21</td><td>90</td><td><a href="#self">Посмотреть темы ↗</a></td></tr><tr class="total-row"><td>Общая трудоёмкость</td><td>5 ECTS</td><td>180</td><td><a href="sources/study-plan.docx" download>Скачать DOCX ↓</a></td></tr></tbody></table></div></section>
    <section class="portal-section"><div class="section-head"><h2>Контроль успеваемости</h2><a class="text-link" href="#assessment">Баллы и допуск ↗</a></div><div class="control-cards">${[['tk','ТК','Текущий контроль','30','Участие в занятиях, практика и самостоятельная работа.','Задания для ТК'],['pk','ПК','Промежуточный контроль','20','Групповая презентация. Вопросы для подготовки.','Подготовка к ПК'],['ik','ИК','Итоговый контроль','50','Тестовая форма. Банк вопросов и условия допуска.','Материалы для ИК']].map(([u,c,t,n,desc,l])=>`<article><div>${tag(c)}<strong>${n}<small> баллов</small></strong></div><h3>${t}</h3><p>${desc}</p><a href="#${u}">${l} →</a></article>`).join('')}</div></section>
    <section class="portal-docbar"><div><span class="shortcut-icon">${icon('files')}</span><div><h3>Основные документы</h3><p>Д.А. Мусаджанова · ${esc(C.meta.university)}</p></div></div><div class="docbar-links"><a href="sources/study-plan.docx" download>Учебный план <span>DOCX ↓</span></a><a href="sources/syllabus.docx" download>Syllabus <span>DOCX ↓</span></a></div></section>`;}

  function primaryDoc(code){const rows=docsFor(code);return rows.find(x=>x.kind==='slides')||rows.find(x=>x.kind==='lecture')||null;}
  function lessonRow(x){const source=primaryDoc(x.code);return `<article class="lesson-row portal-lesson"><span class="row-code">${x.code}</span><div class="lesson-info"><h3><a href="${routeFor(x)}">${esc(x.title)}</a></h3><p>${x.hours} ч · ${docsFor(x.code).length?docsFor(x.code).length+' связанных материалов':'Текст по теме программы'}</p></div><div class="lesson-downloads"><a href="${routeFor(x)}" class="button small secondary">Читать</a>${source?`<a href="${source.file}" class="download-mini" download title="${esc(source.original)}">${source.ext.toUpperCase()} ↓</a>`:`<a href="texts/${x.code}.txt" class="download-mini" download>TXT ↓</a>`}</div></article>`;}
  function course(){return head('Тексты лекций','Темы M1–M20 по учебному плану. Открой текст лекции, связанные материалы или скачай исходный файл.','УЧЕБНЫЕ МАТЕРИАЛЫ · 44 ЧАСА','20')+`<div class="toolbar" id="courseFilters">${[['all','Все темы'],['base','Основы веб-технологий'],['server','PHP и базы данных'],['js','JavaScript'],['project','Разработка приложения']].map(([v,l])=>`<button class="filter ${v==='all'?'active':''}" data-course-filter="${v}">${l}</button>`).join('')}<label class="input-wrap"><span>⌕</span><input id="courseSearch" type="search" placeholder="Название или код темы…" aria-label="Поиск лекций"></label></div><div id="courseResults"></div>`;}

  const GROUPS=[['base','01','Фундамент веба',1,4],['server','02','Серверная сторона',5,7],['js','03','JavaScript и окружение',8,12],['project','04','PHP и целое приложение',13,20]];
  function renderCourse(filter='all',q=''){let count=0;$('#courseResults').innerHTML=GROUPS.filter(g=>filter==='all'||g[0]===filter).map(([key,n,title,start,end])=>{const rows=C.lectures.slice(start-1,end).filter(x=>(x.code+' '+x.title+' '+x.short+' '+x.body).toLowerCase().includes(q.toLowerCase().trim()));count+=rows.length;return rows.length?`<section class="course-group"><div class="group-heading"><strong>${n}</strong><h2>${title}</h2><span>${rows.reduce((s,x)=>s+x.hours,0)} часов</span></div>${rows.map(lessonRow).join('')}</section>`:'';}).join('');if(!count)$('#courseResults').innerHTML=empty('Ничего не нашлось','Попробуй другое название или код темы.','#course','Сбросить поиск');}
  function practice(){return head('Задания для практики','Задания A1–A15 по учебному плану: условия, порядок выполнения и материалы для скачивания.','ПРАКТИЧЕСКИЕ ЗАНЯТИЯ · 46 ЧАСОВ','15')+practiceTabs('practice')+`<div class="card-grid">${C.practices.map(x=>`<article class="item-card"><div class="card-top">${tag(x.code,'violet')}<span class="mono muted" style="font-size:10px">${x.hours} ч ${isDone(x.code)?'· ✓':''}</span></div><h3><a href="${routeFor(x)}">${esc(x.short)}</a></h3><p>${esc(x.task)}</p><div class="card-bottom"><a class="download-mini" href="texts/${x.code}.txt" download>Задание · TXT ↓</a>${btn('Открыть ↗',routeFor(x),'small secondary')}</div></article>`).join('')}</div>`;}
  function labs(){return head('Лабораторные работы','Материалы 14 лабораторных работ из учебного комплекта: оригинальные файлы и методические разборы.','ПРАКТИЧЕСКИЕ МАТЕРИАЛЫ','14')+practiceTabs('labs')+callout('Как читать номера','№ — номер файла из архива, а не номер темы силабуса. Лабораторной №13 в комплекте нет. Отдельные лабораторные часы силабусом не выделены.')+`<div class="card-grid">${C.labs.map(x=>`<article class="item-card"><div class="card-top">${tag(`АРХИВ / №${String(x.number).padStart(2,'0')}`,'violet')}${bookmark(x.code)}</div><div class="lab-symbol" aria-hidden="true">${x.number===1?'[ ]':x.number===7?'PDO':x.number===10?'SQL':x.number===11||x.number===14?'{ }':'↳'}</div><h3><a href="${routeFor(x)}">${esc(x.title)}</a></h3><p>${esc(x.environment)}</p><div class="card-bottom"><span>${x.supplementary?'Дополнение':x.refs.filter(r=>r.startsWith('M')).join(' · ')}</span>${btn('В лабораторию ↗',routeFor(x),'small secondary')}</div></article>`).join('')}</div>`;}
  function readerTop(back,label,key){return `<div class="reader-topline"><a class="text-link" href="${back}">← ${esc(label)}</a><div class="card-top">${tag(key)}${bookmark(key)}</div></div>`;}
  function sourcesAside(code){const docs=docsFor(code);return `<div class="aside-block"><h3>Связанные исходники · ${docs.length}</h3>${docs.length?docs.map(x=>`<a href="${routeFor(x)}"><span class="aside-code">${x.ext.toUpperCase()} · ${x.original}</span>${esc(x.title)}</a>`).join(''):'<p>Отдельного исходника по этой теме в комплекте нет. Основной текст — подготовленный учебный разбор.</p>'}</div>`;}
  function associatedAside(code){const prs=C.practices.filter(x=>x.lesson===code);const labs=C.labs.filter(x=>x.refs.includes(code));return `${prs.length?`<div class="aside-block"><h3>Практические задания</h3>${prs.map(x=>`<a href="${routeFor(x)}"><span class="aside-code">${x.code} / ${x.hours} ч</span>${esc(x.short)}</a>`).join('')}</div>`:''}${labs.length?`<div class="aside-block"><h3>Лабораторные разборы</h3>${labs.map(x=>`<a href="${routeFor(x)}"><span class="aside-code">Архив №${x.number}</span>${esc(x.title)}</a>`).join('')}</div>`:''}`;}
  function actions(x,label='Отметить просмотренным'){return `<div class="reader-actions"><button class="button ${isDone(x.code)?'secondary':''}" data-done="${x.code}">${isDone(x.code)?'✓ Просмотрено · отменить':label+' ✓'}</button><a class="button secondary" href="texts/${x.code}.txt" download>Скачать текст ↓</a><button class="button ghost" data-print>Печать</button></div>`;}
  function lesson(id){const x=C.lectures.find(x=>x.code===id);if(!x)return notFound();state.last=x.code;save();const idx=C.lectures.indexOf(x);return `${readerTop('#course','Тексты лекций',id)}<div class="reader-layout"><article class="reader"><div class="eyebrow"><span class="slash">/</span> ЛЕКЦИЯ ${x.code} <span>· ${x.hours} ЧАСА ПО СИЛАБУСУ</span></div><h1 class="reader-title">${esc(x.title)}</h1><div class="official"><div class="eyebrow">СОДЕРЖАНИЕ ПО СИЛАБУСУ</div><p>${esc(x.body)}</p></div><div class="eyebrow">УЧЕБНЫЙ РАЗБОР <span class="slash">/</span> ${x.outcomes.join(' · ')}</div>${x.sections.map((s,i)=>`<section class="reader-section" id="section${i}"><h2>${esc(s.title)}</h2><p>${esc(s.text)}</p></section>`).join('')}<section class="reader-section"><h2>Пример по теме</h2>${codeBlock(x.lang,x.example)}<div class="result-text"><strong>Результат примера.</strong> ${esc(x.result)}</div></section>${callout('Обрати внимание',x.pitfall,true)}<section class="reader-section"><h2>Вопросы для самопроверки</h2>${qa(x.qa)}</section>${actions(x)}<div class="reader-navigation">${idx?`<a href="${routeFor(C.lectures[idx-1])}"><small>← Предыдущая тема</small>${esc(C.lectures[idx-1].short)}</a>`:'<span></span>'}${idx<19?`<a href="${routeFor(C.lectures[idx+1])}"><small>Следующая тема →</small>${esc(C.lectures[idx+1].short)}</a>`:`<a href="#practice"><small>Практические занятия →</small>Практические задания</a>`}</div></article><aside class="reader-aside"><div class="aside-block"><h3>В этой теме</h3>${x.sections.map((s,i)=>`<a href="#lesson/${id}" data-anchor="section${i}">${String(i+1).padStart(2,'0')} ${esc(s.title)}</a>`).join('')}<p style="margin-top:12px">Основной текст — подготовленный учебный разбор. Оригинальные документы доступны ниже.</p></div>${associatedAside(id)}${sourcesAside(id)}</aside></div>`;}
  function checks(x){return `<div class="checks">${x.checks.map((s,i)=>`<label><input type="checkbox" data-check="${x.code}:${i}" ${state.checks[x.code+':'+i]?'checked':''}><span>${esc(s)}</span></label>`).join('')}</div><p class="check-summary" id="checkSummary">Чек-лист для самопроверки; не официальная оценка.</p>`;}
  function task(id){const x=C.practices.find(x=>x.code===id);if(!x)return notFound();return `${readerTop('#practice','Практические задания',id)}<div class="reader-layout"><article class="reader"><div class="eyebrow"><span class="slash">/</span> ПРАКТИКА ${id} · ${x.hours} ЧАСА</div><h1 class="reader-title">${esc(x.title)}</h1><div class="official"><div class="eyebrow">ЗАДАНИЕ ИЗ СИЛАБУСА</div><p>${esc(x.task)}</p></div><div class="reader-section"><h2>План работы</h2><p>${esc(x.origin)}. Объём и критерии сдачи уточняй у преподавателя.</p><ol class="step-list">${x.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></div><section class="reader-section"><h2>Перед сдачей</h2>${checks(x)}</section>${callout('Результат работы',x.deliver)}${actions(x,'Отметить выполненным')}</article><aside class="reader-aside"><div class="aside-block"><h3>Связанная лекция</h3><a href="#lesson/${x.lesson}"><span class="aside-code">${x.lesson}</span>${esc(C.lectures.find(l=>l.code===x.lesson).short)}</a><p>Шаги и чек-лист подготовлены для сайта. Исходное задание показано дословно.</p></div>${sourcesAside(id)}<div class="aside-block"><h3>Отчёт</h3><p>Цель → ход работы → код → проверки → результат. Не выдавай невыполненный тест за успешный.</p></div></aside></div>`;}
  function lab(id){const x=C.labs.find(x=>x.code===id);if(!x)return notFound();const source=C.docs.find(d=>d.id===x.source);return `${readerTop('#labs','Все лабораторные',id)}<div class="reader-layout"><article class="reader"><div class="eyebrow"><span class="slash">/</span> АРХИВНАЯ ЛАБОРАТОРНАЯ №${x.number}</div><h1 class="reader-title">${esc(x.title)}</h1><p class="reader-subtitle">${esc(x.origin)}. ${x.supplementary?'Дополнительный материал вне отдельных тем программы.':'Связь с программой: '+x.refs.join(', ')+'.'}</p>${callout('Что нужно для запуска',x.environment)}${callout('Уточнение к исходнику',x.note,true)}<section class="reader-section"><h2>Ход работы</h2><ol class="step-list">${x.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></section><section class="reader-section"><h2>Исправленный пример</h2>${codeBlock(x.lang,x.example)}${['php','sql'].includes(x.lang)?'<p>PHP и SQL выполняются в локальном окружении, описанном выше. Этот учебный сайт не запускает серверный код.</p>':''}${x.number===11?`<p>Создай рядом файл users.json:</p>${codeBlock('json',JSON.stringify([{id:1,name:'Тимур',email:'timur@example.test'},{id:2,name:'Мария',email:'maria@example.test'}],null,2))}`:''}</section><section class="reader-section"><h2>Проверка результата</h2>${checks(x)}</section>${actions(x,'Разбор выполнен')}</article><aside class="reader-aside"><div class="aside-block"><h3>Исходный документ</h3><a href="${routeFor(source)}"><span class="aside-code">${source.original}</span>Прочитать оригинал ↗</a><a href="${source.file}" download>Скачать ${source.ext.toUpperCase()} ↓</a><p>Исходник сохранён без изменения. Пример в основном тексте — исправленная учебная версия.</p></div><div class="aside-block"><h3>Связанные темы</h3>${x.refs.map(r=>{const item=ALL_ITEMS.find(i=>i.code===r);return item?`<a href="${routeFor(item)}"><span class="aside-code">${r}</span>${esc(item.short||item.title)}</a>`:'';}).join('')||'<p>Дополнительная тема из архива; отдельных часов в силабусе для неё нет.</p>'}</div><div class="aside-block"><h3>Готовые файлы</h3><a href="examples/todo.html" target="_blank" rel="noopener">Рабочий To-Do ↗</a><a href="examples/ajax.html" target="_blank" rel="noopener">Рабочий AJAX ↗</a><a href="examples/users.json" download>users.json ↓</a><a href="examples/crud.sql" download>CRUD SQL ↓</a></div></aside></div>`;}
  function library(){return head('Библиотека материалов','Лекции, практические и лабораторные работы, презентации и экзаменационные вопросы. Можно прочитать онлайн или скачать.','МАТЕРИАЛЫ ДИСЦИПЛИНЫ','65')+`<div class="toolbar" id="libraryFilters">${[['all','Все'],['lecture','Лекции'],['practice','Практики'],['lab','Лабораторные'],['slides','PDF'],['extra','Дополнения'],['notes','С примечаниями']].map(([v,l])=>`<button class="filter ${v==='all'?'active':''}" data-lib-filter="${v}">${l}</button>`).join('')}<label class="input-wrap"><span>⌕</span><input id="librarySearch" type="search" placeholder="Искать в полных текстах…" aria-label="Поиск в исходных материалах"></label></div><div id="libraryCount" class="eyebrow" style="font-size:8px;margin-bottom:14px"></div><div class="library-list" id="libraryResults"></div><div class="archive-note">Номер в имени исходника сохранён. Все соответствия темам и замечания доступны в <a href="correspondence.csv" download style="color:var(--accent)">таблице соответствий CSV ↓</a>.</div>`;}
  function fileRow(x){return `<article class="file-row"><div class="file-type ${x.ext}">${x.ext.toUpperCase()}</div><div class="file-info"><h3><a href="${routeFor(x)}">${esc(x.title)}</a></h3><p>${esc(x.original)} · ${size(x.size)} · ${KINDS[x.kind]}${x.language==='uz'?' · Узбекский':''}${x.duplicateOf?' · Дубль '+x.duplicateOf:''}${x.note?' · Есть примечание':''}</p></div><div class="file-refs">${x.refs.length?x.refs.slice(0,4).map(r=>tag(r)).join(''):'Дополнение'}</div><div class="file-actions"><a class="read-link" href="${routeFor(x)}">Читать ↗</a><a class="icon-button" href="${x.file}" download aria-label="Скачать ${esc(x.original)}" title="Скачать оригинал">↓</a></div></article>`;}
  function renderLibrary(filter='all',query=''){const q=query.toLowerCase().trim();const rows=C.docs.filter(x=>(filter==='all'||filter==='extra'&&x.supplementary||filter==='notes'&&x.note||filter==='lecture'&&x.kind==='lecture'||filter===x.kind)&&(!q||(x.title+' '+x.original+' '+x.refs.join(' ')+' '+x.text).toLowerCase().includes(q)));$('#libraryCount').textContent=`${rows.length} из ${C.docs.length} материалов`;$('#libraryResults').innerHTML=rows.length?rows.map(fileRow).join(''):empty('Ничего не нашлось','Попробуй другой запрос или фильтр.','#library','Сбросить поиск');}
  function material(id){const x=C.docs.find(x=>x.id===id);if(!x)return notFound();const labs=C.labs.filter(l=>l.source===id||l.refs.some(r=>x.refs.includes(r)));return `${readerTop('#library','Все материалы',id)}<div class="reader-layout"><article class="reader"><div class="eyebrow"><span class="slash">/</span> ${esc(KINDS[x.kind])} · ${x.ext.toUpperCase()}</div><h1 class="reader-title">${esc(x.title)}</h1><p class="reader-subtitle">${esc(x.original)} · ${size(x.size)} ${x.language==='uz'?'· Оригинал на узбекском языке':''}</p>${x.duplicateOf?callout('Повтор материала','Основной текст совпадает с '+x.duplicateOf+' после удаления первой строки с обозначением работы. Оба оригинала сохранены.'):''}${x.note?callout('Примечание к исходнику',x.note,true):''}${callout('Исходный материал','Ниже содержимое исходного файла без редакторской правки. Исправленные учебные разборы находятся по связанным темам. Наличие файла не означает полное покрытие темы силабуса.')}<div class="reader-actions"><a class="button" href="${x.file}" download>Скачать оригинал ↓</a>${x.ext==='pdf'?`<a class="button secondary" href="${x.file}" target="_blank" rel="noopener">Открыть PDF ↗</a>`:''}</div>${x.ext==='pdf'?`<iframe class="pdf-frame" src="${x.file}" title="PDF: ${esc(x.title)}" loading="lazy"></iframe><p class="archive-note">Если встроенный просмотр недоступен, используй «Открыть PDF». Текстовый слой ниже не содержит текст внутри картинок слайдов.</p>`:''}${x.ext==='pptx'?callout('Просмотр презентации','Текст слайдов приведён ниже. Чтобы увидеть иллюстрации и исходное оформление, скачай PPTX.'):''}${x.correctedExample?`<section class="reader-section"><h2>Дополнительный исправленный пример</h2><p>${esc(x.correctedContext)}</p>${codeBlock(x.correctedLang,x.correctedExample)}</section>`:''}<section class="reader-section"><h2>${x.ext==='pdf'?'Текстовый слой PDF':x.ext==='pptx'?'Текст слайдов':'Полный текст документа'}</h2><pre class="source-text">${esc(x.text)}</pre></section></article><aside class="reader-aside"><div class="aside-block"><h3>Связь с программой</h3>${x.refs.map(r=>{const item=ALL_ITEMS.find(i=>i.code===r);return item?`<a href="${routeFor(item)}"><span class="aside-code">${r}</span>${esc(item.short||item.title)}</a>`:'';}).join('')||'<p>Дополнительный материал; отдельная тема и часы не назначены.</p>'}</div>${labs.length?`<div class="aside-block"><h3>Учебные разборы</h3>${labs.slice(0,5).map(l=>`<a href="${routeFor(l)}"><span class="aside-code">Архив №${l.number}</span>${esc(l.title)}</a>`).join('')}</div>`:''}<div class="aside-block"><h3>Происхождение</h3><p>Загруженный комплект учебных материалов. Имя и байты исходного файла сохранены.</p><p style="margin-top:8px">Идентификатор: ${id}</p></div></aside></div>`;}
  function self(){return head('Самостоятельная работа','21 тема по учебному плану, 90 часов. Открой тему, требования и связанные материалы.','САМОСТОЯТЕЛЬНАЯ РАБОТА · СРС','21')+practiceTabs('self')+callout('Что требует силабус','Треть заданий выполняется в малых группах с оценкой индивидуального вклада. В текущем контроле предусмотрены две самостоятельные работы по 5 баллов. Выбор тем, распределение и сроки сообщает преподаватель.')+`<div class="card-grid">${C.srs.map(x=>`<article class="item-card srs-card"><div class="card-top">${tag(x.code,'peach')}<span class="mono muted" style="font-size:10px">${x.hours} ч ${isDone(x.code)?'· ✓':''}</span></div><h3><a href="${routeFor(x)}">${esc(x.title)}</a></h3><p>${esc(x.short)}</p><div class="card-bottom"><span>Предложение к выполнению</span>${btn('Разобраться ↗',routeFor(x),'small secondary')}</div></article>`).join('')}</div>`;}
  function selfstudy(id){const x=C.srs.find(x=>x.code===id);if(!x)return notFound();return `${readerTop('#self','Самостоятельная работа',id)}<div class="reader-layout"><article class="reader"><div class="eyebrow"><span class="slash">/</span> ${id} · ${x.hours} ЧАСА ПО ПРОГРАММЕ</div><h1 class="reader-title">${esc(x.title)}</h1><section class="reader-section"><h2>${esc(x.short)}</h2><p>${esc(x.suggestion)}</p></section>${callout('Предлагаемый результат',x.deliver)}${callout('Статус рекомендации',x.origin+'. Конкретную тему, формат, распределение по группам и срок подтверждает преподаватель.')}<section class="reader-section"><h2>Как оформить работу</h2><ol class="step-list"><li>Укажи тему, цель и использованные источники.</li><li>Покажи свой результат и объясни принятые решения.</li><li>Запиши проверки, ограничения и свой вывод.</li><li>При работе в группе отдельно обозначь свой вклад.</li></ol></section><div class="reader-actions"><button class="button ${isDone(id)?'secondary':''}" data-done="${id}">${isDone(id)?'✓ Выполнено · отменить':'Отметить выполненным ✓'}</button><button class="button secondary" data-print>Печать</button></div></article><aside class="reader-aside">${sourcesAside(id)}${x.lessons.length?`<div class="aside-block"><h3>Поможет теория</h3>${x.lessons.map(r=>`<a href="#lesson/${r}"><span class="aside-code">${r}</span>${esc(C.lectures.find(l=>l.code===r).short)}</a>`).join('')}</div>`:''}<div class="aside-block"><h3>Академические требования</h3><p>В силабусе: оригинальность не ниже 70%, проверка до двух раз. Сроки объявляет преподаватель. Смотри полный исходный документ.</p></div></aside></div>`;}
  function assessment(){return head('Баллы и условия допуска','Порядок контроля и баллы — из разделов 8–9 силабуса. Калькулятор показывает выполнение порогов, а не ставит официальную оценку.','06 / КОНТРОЛЬ','100')+`<div class="assessment-grid"><section class="grade-card"><h2>Твои баллы</h2><p>Введи фактические баллы. ТК + ПК определяют допуск; итоговый контроль проверяется отдельно.</p><div class="grade-fields"><label>ТК · из 30<input type="number" id="tk" min="0" max="30" step="1" value="0"></label><label>ПК · из 20<input type="number" id="pk" min="0" max="20" step="1" value="0"></label><label>ИК · из 50<input type="number" id="ik" min="0" max="50" step="1" value="0"></label></div><div class="grade-result" id="gradeResult" aria-live="polite"></div></section><section class="grade-card"><h2>Из чего складываются 100</h2>${[['Участие в занятиях','10'],['Активность на практике','10'],['Две самостоятельные работы','5 + 5'],['Промежуточный контроль · презентация','20'],['Итоговый контроль · тест','50']].map(([a,b])=>`<div class="grade-line"><span>${a}</span><strong>${b}</strong></div>`).join('')}<p style="margin-top:20px">Допуск: минимум 30 из 50 за ТК + ПК.<br>Итоговый контроль: минимум 30 из 50.</p></section></div>${callout('У суммы есть два отдельных условия','Даже большая общая сумма не компенсирует ИК ниже 30. Числовые границы оценок «3/4/5» в этом документе не заданы — сайт их не придумывает.')}<section class="reader-section"><h2>Что подготовить</h2><div class="table-wrap"><table><thead><tr><th>Работа</th><th>Формат по силабусу</th><th>Баллы</th></tr></thead><tbody><tr><td>Самостоятельная №1</td><td>Эссе или письменная работа по выбранной теме. Объём в документе: «не менее 1000–1200 слов»; точный минимум уточни у преподавателя.</td><td>5</td></tr><tr><td>Самостоятельная №2</td><td>Бизнес-ориентированный проект и защита.</td><td>5</td></tr><tr><td>Промежуточный контроль</td><td>Презентация в малой группе.</td><td>20</td></tr><tr><td>Итоговый контроль</td><td>Тестовая форма. Даты и условия сообщает преподаватель.</td><td>50</td></tr></tbody></table></div></section><section class="reader-section"><h2>Архив экзаменационных вопросов</h2><p>Банк 2025 года содержит дубли, устаревшие теги и спорные ключи. Он не используется здесь для автоматического выставления баллов.</p><div style="margin-top:17px">${btn('Посмотреть с примечанием ↗','#material/D064','secondary')}</div></section><section class="reader-section"><h2>Вопросы по темам дисциплины</h2><p>Открытые вопросы и объяснения в каждой из 20 тем охватывают материал учебной программы.</p><div style="margin-top:17px">${btn('Открыть лекции ↗','#course','secondary')}</div></section>`;}
  function grade(){const inputs=['tk','pk','ik'].map(id=>$('#'+id));const values=inputs.map(x=>x.value.trim()===''?NaN:Number(x.value));const [tk,pk,ik]=values;if(values.some((x,i)=>!Number.isFinite(x)||x<0||x>[30,20,50][i]||!Number.isInteger(x))){$('#gradeResult').innerHTML='<p>Укажи целые баллы: ТК 0–30, ПК 0–20, ИК 0–50.</p>';return;}const admitted=tk+pk>=30,passed=admitted&&ik>=30;$('#gradeResult').innerHTML=`<strong>${tk+pk+ik}<span style="font-size:18px;color:var(--muted)"> / 100</span></strong><p>${admitted?'✓ Порог допуска выполнен':'Порог допуска: '+(tk+pk)+' / 30 — ещё '+(30-tk-pk)+' б.'}</p><p>${ik>=30?'✓ Порог итогового контроля выполнен':'ИК: '+ik+' / 30 — ещё '+(30-ik)+' б.'}</p><p style="color:${passed?'var(--accent)':'var(--muted)'}">${passed?'Оба порога выполнены. Официальный результат подтверждает преподаватель.':'По введённым баллам оба условия ещё не выполнены.'}</p>`;}
  const OUTCOMES=['Объясняет клиент-серверную архитектуру, назначение HTTP, HTML, CSS, JavaScript и PHP.','Обосновывает разделение представления, обработки данных и доступа к базе в структуре веб-приложения.','Создаёт семантическую HTML-страницу и оформляет её с помощью CSS.','Реализует обработку событий и изменение содержимого страницы средствами JavaScript.','Разрабатывает PHP-скрипты, обрабатывает формы и выполняет запросы к базе данных.','Настраивает локальный сервер, тестирует сценарии приложения и применяет проверку пользовательского ввода.'];
  function about(){return head('О дисциплине','Одна точка опоры — загруженный силабус. Исходники сохранены, исправленные разборы и методические дополнения обозначены отдельно.','О ДИСЦИПЛИНЕ','I')+`<div class="about-columns"><div><h2>${esc(C.meta.title)}</h2><p style="margin-top:15px">${esc(C.meta.university)}.</p><p style="margin-top:15px">Цель дисциплины — сформировать основы проектирования и разработки динамических веб-приложений с использованием клиентских и серверных технологий.</p><div class="export-row"><a class="button" href="sources/syllabus.docx" download>Силабус DOCX ↓</a><a class="button secondary" href="correspondence.csv" download>Карта материалов CSV ↓</a><a class="button secondary" href="AUDIT.md" download>Отчёт о сверке ↓</a></div></div><dl class="fact-list">${[['Дисциплина','Веб технологии I'],['Учебный год','2026–2027'],['Семестр','5'],['Язык','Русский'],['Кредиты','5 ECTS — как в источнике'],['Объём','180 ч · 44 + 46 + 90'],['Составитель','Д.А. Мусаджанова']].map(([a,b])=>`<div><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl></div><section class="reader-section"><h2>Результаты обучения</h2>${OUTCOMES.map((x,i)=>`<div class="outcome"><strong>TN${i+1}</strong><span>${x}</span></div>`).join('')}</section><section class="reader-section"><h2>Что важно знать о комплекте</h2><div class="issues-grid" style="margin-top:20px">${C.issues.map(x=>`<article class="issue"><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p></article>`).join('')}</div></section><section class="reader-section"><h2>Проверяемые соответствия</h2><p>Связь с темой не означает полного покрытия каждого пункта. Для официальных заданий созданы методические инструкции. Лабораторные номера сохранены только как обозначения исходного архива.</p><div class="table-wrap" style="margin-top:20px"><table><thead><tr><th>Тема</th><th>Часы</th><th>Связанные исходники</th><th>Учебный разбор</th></tr></thead><tbody>${[...C.lectures,...C.practices].map(x=>`<tr><td><a href="${routeFor(x)}">${x.code} · ${esc(x.title)}</a></td><td>${x.hours}</td><td>${docsFor(x.code).map(d=>`<a href="${routeFor(d)}">${d.id}</a>`).join(', ')||'Отдельного исходника нет'}</td><td>Подготовлен для сайта</td></tr>`).join('')}</tbody></table></div></section><section class="reader-section"><h2>Справочная документация</h2><p>Для уточнения синтаксиса и поведения API; это дополнение к загруженным материалам.</p><div class="resource-links" style="margin-top:18px">${C.references.map(x=>`<a class="button small secondary" href="${x.url}" target="_blank" rel="noopener">${esc(x.title)} ↗</a>`).join('')}</div></section><details class="question"><summary>Полный текст силабуса, включая литературу и академические требования</summary><pre class="source-text" style="margin-top:18px">${esc(C.syllabusText)}</pre></details><section class="reader-section"><h2>Прогресс на твоём устройстве</h2><p>Изученные темы, сохранённое и чек-листы хранятся только в этом браузере. Учётной записи и отправки работ преподавателю нет. Экспорт позволяет сохранить копию отметок.</p><div class="export-row"><button class="button secondary" data-export>Экспортировать прогресс ↓</button></div></section>`;}
  function saved(){const rows=ALL_ITEMS.filter(x=>isSaved(x.code||x.id));const done=ALL_ITEMS.filter(x=>isDone(x.code||x.id));return head('Избранные материалы','Возвращайся к важному. Сохранённые материалы и отметки доступны в этом браузере.','ЛИЧНОЕ ПРОСТРАНСТВО',String(rows.length).padStart(2,'0'))+(rows.length?`<div class="card-grid">${rows.map(x=>`<article class="item-card"><div class="card-top">${tag(x.code||x.id,'lime')}${bookmark(x.code||x.id)}</div><h3><a href="${routeFor(x)}">${esc(x.short||x.title)}</a></h3><p>${esc(x.id?KINDS[x.kind]:x.origin||'Учебный материал')}</p><div class="card-bottom"><span>${isDone(x.code)?'✓ Просмотрено':''}</span>${btn('Открыть ↗',routeFor(x),'small secondary')}</div></article>`).join('')}</div>`:empty('Здесь будет важное','Нажми на звёздочку внутри темы, задания или исходного материала.'))+`<section class="reader-section"><h2>Отмечено выполненным · ${done.length}</h2>${done.length?done.map(x=>`<a class="lesson-row" href="${routeFor(x)}"><span class="row-code done-mark">✓</span><h3>${esc(x.code)} · ${esc(x.short||x.title)}</h3><span class="row-meta">↗</span></a>`).join(''):'<p>Отметки появятся после нажатия «Просмотрено» или «Выполнено» в материале.</p>'}</section><div class="export-row"><button class="button secondary" data-export>Экспортировать прогресс ↓</button></div>`;}
  const playgroundTemplates={counter:'<!doctype html>\n<html lang="ru">\n<head><meta charset="UTF-8"><style>\nbody{font-family:system-ui;padding:36px;color:#20291f;background:#f8faf4}\nh1{font-size:32px}button{background:#20291f;color:#c5f277;border:0;border-radius:12px;padding:18px 24px;font-size:18px;cursor:pointer}\n</style></head>\n<body>\n<h1>Пусть код оживёт.</h1>\n<p>Измени текст или цвет и нажми «Запустить».</p>\n<button id="count">Нажатий: 0</button>\n<script>\nlet count = 0;\nconst button = document.querySelector("#count");\nbutton.addEventListener("click", () => {\n  count += 1;\n  button.textContent = `Нажатий: ${count}`;\n});\n</script>\n</body></html>',card:'<!doctype html>\n<html lang="ru"><head><meta charset="UTF-8"><style>\nbody{background:#eaf0df;color:#21301b;font:16px/1.6 system-ui;padding:32px}\narticle{max-width:280px;background:white;border-radius:24px;padding:32px;box-shadow:0 12px 25px #24361915}\nspan{font-family:monospace;color:#647c4d}h1{font-size:32px;line-height:1.2}a{display:inline-block;background:#21301b;color:#dcffa7;padding:10px 20px;border-radius:6px;text-decoration:none}\n</style></head><body>\n<article><span>M2 / HTML + CSS</span><h1>Твой первый интерфейс.</h1><p>Смысл, структура и немного воздуха.</p><a href="#more">Узнать больше →</a><p id="more">Привет из твоего проекта!</p></article>\n</body></html>',array:'<!doctype html>\n<html lang="ru"><head><meta charset="UTF-8"><style>body{font:18px/1.7 system-ui;padding:28px}li{padding:8px;border-bottom:1px solid #ddd}</style></head>\n<body><h1>Из массива — на страницу</h1><ul id="list"></ul>\n<script>\nconst students = [\n  {name:"Тимур",score:85},\n  {name:"Мария",score:92},\n  {name:"Али",score:45}\n];\nconst list = document.querySelector("#list");\nstudents.filter(student => student.score >= 60).forEach(student => {\n  const li = document.createElement("li");\n  li.textContent = `${student.name} — ${student.score}`;\n  list.append(li);\n});\n</script></body></html>'};
  function playground(){return head('Примеры HTML, CSS и JavaScript','Мини-песочница для HTML, CSS и JavaScript. Результат рядом с кодом — можно спокойно экспериментировать.','08 / PLAYGROUND','↯')+`<div class="playground"><div class="playground-bar">${[['counter','Счётчик'],['card','Карточка'],['array','Массив']].map(([v,t])=>`<button class="filter ${v==='counter'?'active':''}" data-template="${v}">${t}</button>`).join('')}<button class="button small" data-run>Запустить ▶</button></div><div class="playground-grid"><div class="editor-pane"><label for="codeEditor">INDEX.HTML · HTML / CSS / JS</label><textarea id="codeEditor" spellcheck="false" autocapitalize="off" aria-label="Редактор HTML, CSS и JavaScript"></textarea></div><div class="preview-pane"><p>РЕЗУЛЬТАТ · ИЗОЛИРОВАННЫЙ ПРОСМОТР</p><iframe id="codePreview" sandbox="allow-scripts" title="Результат выполнения учебного кода"></iframe></div></div></div><p class="sandbox-note">Запуск — по кнопке. Выбор другого примера заменяет содержимое редактора. Изменения здесь не сохраняются. PHP и SQL запускаются в локальном окружении по инструкции M12.</p><div class="export-row"><button class="button secondary" data-download-code>Скачать свой index.html ↓</button>${btn('Примеры и лабораторные ↗','#labs','secondary')}</div>`;}
  function runCode(){const frame=$('#codePreview');const source=$('#codeEditor').value;frame.srcdoc='<meta http-equiv="Content-Security-Policy" content="default-src \'none\'; script-src \'unsafe-inline\'; style-src \'unsafe-inline\'; img-src data:; font-src data:; connect-src \'none\'; form-action \'none\'">'+source;}
  function download(name,text,type='text/plain;charset=utf-8'){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
  function practiceTabs(active){return `<div class="section-tabs" aria-label="Практические материалы">${[['practice','Практические задания · 15'],['labs','Лабораторные работы · 14'],['self','Самостоятельная работа · 21']].map(([u,t])=>`<a href="#${u}" class="${u===active?'active':''}" ${u===active?'aria-current="page"':''}>${t}</a>`).join('')}</div>`;}
  function calendar(){return head('Календарный план','Темы, последовательность и объём занятий по программе дисциплины. Лекции и практика доступны в одном перечне.','КАЛЕНДАРНО-ТЕМАТИЧЕСКИЙ ПЛАН','90')+`<div class="calendar-docstrip"><span>${icon('info')} Даты занятий и контроля определяются расписанием университета. В учебной программе конкретные даты не указаны.</span><a href="calendar-plan.csv" download>Скачать план CSV ↓</a></div><div class="toolbar" id="calendarFilters">${[['all','Все занятия · 90 ч'],['M','Лекции · 44 ч'],['A','Практика · 46 ч']].map(([k,t])=>`<button class="filter ${k==='all'?'active':''}" data-calendar-filter="${k}">${t}</button>`).join('')}<label class="input-wrap"><span>⌕</span><input type="search" id="calendarSearch" placeholder="Тема или код…" aria-label="Поиск в календарном плане"></label></div><div id="calendarResults"></div><div class="plan-bottomlinks">${btn('Самостоятельная работа · 90 ч →','#self','secondary')}${btn('Учебный план DOCX ↓','sources/study-plan.docx','secondary download-link')}<button class="button ghost" data-print>Печать</button></div>`;}
  function renderCalendar(type='all',query=''){const rows=[...C.lectures.map(x=>({...x,type:'M'})),...C.practices.map(x=>({...x,type:'A'}))].filter(x=>(type==='all'||x.type===type)&&(x.code+' '+x.title+' '+(x.body||x.task)).toLowerCase().includes(query.toLowerCase().trim()));$('#calendarResults').innerHTML=rows.length?`<div class="table-wrap"><table class="calendar-table"><thead><tr><th>Код</th><th>Тема занятия</th><th>Вид</th><th>Часы</th><th>Материалы</th></tr></thead><tbody>${rows.map(x=>`<tr><td><span class="row-code">${x.code}</span></td><td><a href="${routeFor(x)}">${esc(x.title)}</a><p class="table-note">${esc(x.body||x.task)}</p></td><td>${x.type==='M'?'Лекция':'Практика'}</td><td>${x.hours}</td><td><a href="${routeFor(x)}">Открыть ↗</a></td></tr>`).join('')}<tr class="total-row"><td colspan="3">Всего по выбранным занятиям</td><td>${rows.reduce((a,x)=>a+x.hours,0)}</td><td>${rows.length} тем</td></tr></tbody></table></div>`:empty('Темы не найдены','Измени запрос или выбери другой вид занятий.','#calendar','Показать весь план');}
  function syllabus(){return head('Syllabus','Учебная программа дисциплины «Веб технологии I»: результаты обучения, содержание, требования и порядок оценивания.','ОСНОВНОЙ ДОКУМЕНТ','I')+`<div class="document-cover"><div class="cover-icon">${icon('book')}</div><div><span class="eyebrow">2026–2027 · 5 СЕМЕСТР</span><h2>Веб технологии I</h2><p>${esc(C.meta.university)}</p><p>Составитель: ${esc(C.meta.teacher)} · Язык обучения: русский</p></div><div class="cover-actions"><a class="button" href="sources/syllabus.docx" download>Скачать Syllabus ↓<small>DOCX</small></a><button class="button secondary" data-print>Распечатать страницу</button></div></div><div class="syllabus-content"><section><h2>Цель дисциплины</h2><p>Сформировать основы проектирования и разработки динамических веб-приложений с использованием клиентских и серверных технологий.</p><p>В программе: HTML, CSS, JavaScript, PHP, взаимодействие с базой данных и настройка локального веб-сервера.</p></section><section><h2>Учебная нагрузка</h2><div class="table-wrap"><table><thead><tr><th>Лекции</th><th>Практические занятия</th><th>Самостоятельная работа</th><th>Всего</th><th>ECTS</th></tr></thead><tbody><tr><td>44 ч</td><td>46 ч</td><td>90 ч</td><td>180 ч</td><td>5</td></tr></tbody></table></div></section><section><h2>Результаты обучения</h2>${OUTCOMES.map((x,i)=>`<div class="outcome"><strong>TN${i+1}</strong><span>${esc(x)}</span></div>`).join('')}</section><section><h2>Контроль и оценивание</h2><div class="syllabus-control">${[['tk','ТК · Текущий контроль','30 баллов'],['pk','ПК · Промежуточный контроль','20 баллов'],['ik','ИК · Итоговый контроль','50 баллов']].map(([u,t,n])=>`<a href="#${u}"><span>${t}</span><strong>${n} →</strong></a>`).join('')}</div><p>Для допуска к ИК: ТК + ПК — не менее 30 из 50 баллов. На ИК отдельно требуется не менее 30 из 50 баллов.</p></section><section><h2>Разделы программы</h2><div class="resource-links">${btn('Календарный план ↗','#calendar','secondary')}${btn('Лекции ↗','#course','secondary')}${btn('Практические задания ↗','#practice','secondary')}${btn('Темы СРС ↗','#self','secondary')}</div></section><details class="question"><summary>Полный текст программы, литература и академические требования</summary><pre class="source-text" style="margin-top:18px">${esc(C.syllabusText)}</pre></details></div><p class="document-caption">Исходный документ доступен в DOCX. <a href="#about">Сведения о материалах дисциплины ↗</a></p>`;}
  function tk(){return head('Задания для ТК','Текущий контроль: участие в занятиях, работа на практике и две самостоятельные работы в течение семестра.','ТК · ТЕКУЩИЙ КОНТРОЛЬ','30')+`<div class="control-summary"><div><span>Участие в занятиях</span><strong>10 <small>баллов</small></strong></div><div><span>Активная работа на практике</span><strong>10 <small>баллов</small></strong></div><div><span>Самостоятельная работа</span><strong>10 <small>баллов</small></strong></div></div><section class="portal-section"><div class="section-head"><div><h2>Что нужно подготовить</h2><p>Две самостоятельные работы по выбранным темам программы.</p></div></div><div class="assignment-pair"><article class="assignment-card"><div class="card-top">${tag('САМОСТОЯТЕЛЬНАЯ №1','lime')}<span>5 баллов</span></div><h3>Письменная работа</h3><p>Эссе или письменная работа по одной из тем самостоятельного обучения. В программе объём указан как «не менее 1000–1200 слов»; точный минимум уточняется у преподавателя.</p><div class="assignment-detail"><span>Срок сдачи</span><b>Объявляет преподаватель</b></div>${btn('Выбрать тему СРС →','#self','secondary')}</article><article class="assignment-card"><div class="card-top">${tag('САМОСТОЯТЕЛЬНАЯ №2','lime')}<span>5 баллов</span></div><h3>Проект и защита</h3><p>Подготовить и защитить бизнес-ориентированный проект по одной из тем самостоятельного обучения. Показать результат, объяснить принятые решения и свой вклад.</p><div class="assignment-detail"><span>Срок сдачи</span><b>Объявляет преподаватель</b></div>${btn('Посмотреть темы →','#self','secondary')}</article></div></section><section class="portal-section"><h2>Практические и самостоятельные занятия</h2><p class="section-description">Условия заданий, материалы и рекомендации по выполнению доступны в соответствующем разделе.</p><div class="resource-links">${btn('Практические задания · 15 ↗','#practice','secondary')}${btn('Лабораторные материалы · 14 ↗','#labs','secondary')}${btn('Темы самостоятельной работы · 21 ↗','#self','secondary')}</div></section>${callout('Работа в малых группах','По программе треть самостоятельных заданий выполняется в малых группах. Индивидуальный вклад оценивается при представлении и защите результата. Распределение тем сообщает преподаватель.')}<div class="plan-bottomlinks">${btn('Требования и критерии в Syllabus →','#syllabus','secondary')}${btn('Вопросы для ПК →','#pk','secondary')}<a class="text-link" href="texts/tk-tasks.txt" download>Скачать требования ТК · TXT ↓</a></div>`;}
  const PC_VARIANTS=[{title:'Вариант 1',questions:[['Значение, цели и задачи применения веб-технологий.','M1'],['Роль и задачи веб-серверных технологий.','M1'],['Базовые концепции разработки веб-приложений.','M1']]},{title:'Вариант 2',questions:[['HTML: структура документа.','M2'],['CSS: основные понятия и определения.','M3'],['Установка веб-сервера на компьютер.','M12']]}];
  function pk(){return head('Вопросы для ПК','Материалы для подготовки к промежуточному контролю: основные вопросы и ссылки на соответствующие лекции.','ПК · ПРОМЕЖУТОЧНЫЙ КОНТРОЛЬ','20')+`<div class="control-notice"><div class="notice-symbol">${icon('self')}</div><div><strong>Формат по программе — презентация в малой группе</strong><p>20 баллов. Срок и конкретное задание объявляет преподаватель. Вопросы ниже предназначены для подготовки; утверждённый перечень в учебной программе не приведён.</p></div></div><section class="portal-section"><div class="section-head"><h2>Варианты для подготовки</h2><a class="button small secondary" href="texts/pk-questions.txt" download>Скачать вопросы ↓</a></div><div class="assignment-pair">${PC_VARIANTS.map(v=>`<article class="assignment-card"><div class="eyebrow">${v.title}</div><ol class="pc-questions">${v.questions.map(([q,ref])=>`<li><p>${esc(q)}</p><a href="#lesson/${ref}">${ref} · открыть лекцию ↗</a></li>`).join('')}</ol></article>`).join('')}</div></section><section class="portal-section"><h2>Вопросы по всем темам дисциплины</h2><p class="section-description">Дополнительная самопроверка с пояснениями. Открой тему, чтобы посмотреть ответ и исходные материалы.</p>${C.lectures.map(x=>`<details class="question"><summary>${x.code} · ${esc(x.title)}</summary><div class="pc-topic-questions">${x.qa.map(q=>`<p>${esc(q.question)}</p>`).join('')}<a href="${routeFor(x)}">Открыть текст лекции и пояснения ↗</a></div></details>`).join('')}</section><div class="plan-bottomlinks">${btn('Тесты для ИК →','#ik','secondary')}${btn('Баллы и условия допуска →','#assessment','secondary')}</div>`;}
  function ik(){return head('Готовься уверенно.','Повтори вопросы и ответы или проверь себя в тренировке.','ИТОГОВЫЙ КОНТРОЛЬ','')+`<section class="exam-hero"><div><span>ВСЁ ДЛЯ ПОДГОТОВКИ</span><h2><b>100</b> вопросов.<br>Понятные ответы.</h2><p>Смотри, разбирайся, пробуй снова.</p></div><div class="exam-orbit" aria-hidden="true"><span>?</span><i>✓</i></div></section><div class="exam-mode-tabs" aria-label="Режим подготовки"><button class="active" data-exam-mode="study" aria-pressed="true">01 <span>Вопросы и ответы</span></button><button data-exam-mode="train" aria-pressed="false">02 <span>Тренировка</span><i>↗</i></button></div><section id="examStudy"><div class="exam-toolbar"><label class="input-wrap"><span>⌕</span><input id="examSearch" type="search" placeholder="Найти вопрос или термин…" aria-label="Поиск вопросов ИК"></label><button class="button secondary" data-exam-reveal>${examAllAnswers?'Скрыть все ответы':'Показать все ответы'}</button><a class="text-link" href="texts/ik-answers.txt" download>Скачать ответы ↓</a></div><div id="examResults"></div><div class="exam-pagination"><button class="button secondary" data-exam-page="prev">← Назад</button><span id="examPageLabel"></span><button class="button secondary" data-exam-page="next">Далее →</button></div><p class="source-footnote">Вопрос №47 содержит два отмеченных ответа и требует уточнения. Повторяющиеся вопросы сохранены.</p><a class="text-link" href="sources/D064.docx" download>Исходный файл · DOCX ↓</a></section><section id="examTraining" hidden></section>`;}
  let examPage=0,examAllAnswers=false,trainingSession=null;
  function renderExam(){const query=($('#examSearch')?.value||'').toLowerCase().trim();const rows=(window.EXAM_BANK||[]).filter(x=>(x.number+' '+x.question+' '+x.options.map(o=>o.text).join(' ')).toLowerCase().includes(query));const pages=Math.max(1,Math.ceil(rows.length/10));examPage=Math.min(examPage,pages-1);$('#examResults').innerHTML=rows.length?rows.slice(examPage*10,examPage*10+10).map(x=>`<article class="exam-question"><div class="exam-qtop"><span>ВОПРОС ${String(x.number).padStart(3,'0')}</span>${x.duplicateOf?`<span>Повтор №${x.duplicateOf}</span>`:''}</div><h2>${esc(x.question)}</h2><ol class="exam-options">${x.options.map((o,i)=>`<li><b>${String.fromCharCode(65+i)}</b><code>${esc(o.text)}</code></li>`).join('')}</ol><details class="answer-panel" ${examAllAnswers?'open':''}><summary>Посмотреть ответ <span>＋</span></summary><div class="answer-content">${x.ambiguous?'<p class="ambiguous-answer">В исходнике два ответа. Уточни правильный вариант у преподавателя.</p>':''}${x.options.map((o,i)=>o.correct?`<div class="correct-option"><span>✓ ${String.fromCharCode(65+i)}</span><code>${esc(o.text)}</code></div>`:'').join('')}</div></details></article>`).join(''):'<div class="empty">Ничего не найдено. Попробуй другой запрос.</div>';$('#examPageLabel').textContent=`${rows.length} вопросов · ${examPage+1} / ${pages}`;$('[data-exam-page="prev"]').disabled=examPage===0;$('[data-exam-page="next"]').disabled=examPage>=pages-1;}
  function switchExamMode(mode){$('#examStudy').hidden=mode!=='study';$('#examTraining').hidden=mode!=='train';$$('[data-exam-mode]').forEach(b=>{const active=b.dataset.examMode===mode;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});if(mode==='train')renderTraining();}
  function renderTraining(){const host=$('#examTraining');if(!host)return;const bank=window.EXAM_BANK||[];const available=bank.filter(x=>!x.ambiguous).length;
    if(!trainingSession){host.innerHTML=`<div class="training-setup"><span class="eyebrow">ТРЕНИРОВКА БЕЗ ОЦЕНОК</span><h2>Проверь, что запомнил.</h2><p>Выбирай ответ и сразу узнавай результат. Вопросы и варианты перемешиваются при каждом запуске.</p><div class="session-options"><label for="trainingCount">Сколько вопросов?</label><select id="trainingCount"><option value="10">10 — короткая разминка</option><option value="20">20 — основательная подготовка</option><option value="${available}">Все ${available} вопросов</option></select><button class="button" data-train-start>Начать тренировку <span>→</span></button></div><small>№47 не участвует в подсчёте: его ключ требует уточнения. Результат тренировки не является оценкой за ИК.</small></div>`;return;}
    const t=trainingSession;
    if(t.finished){const total=t.questions.length;host.innerHTML=`<section class="training-result"><span class="eyebrow">ТРЕНИРОВКА ЗАВЕРШЕНА</span><div class="score-orb"><strong>${t.score}<small>/${total}</small></strong><span>верных ответов</span></div><h2>${t.score===total?'Отлично разобрался.':'Теперь понятно, что повторить.'}</h2><p>${t.mistakes.length?'Ошибок: '+t.mistakes.length+'. Можно пройти только эти вопросы ещё раз.':'Все ответы верны. Для закрепления попробуй новую подборку.'}</p><div class="resource-links">${t.mistakes.length?'<button class="button" data-train-retry>Повторить ошибки ↻</button>':''}<button class="button secondary" data-train-reset>Новая тренировка</button></div>${t.mistakes.length?`<div class="mistake-list">${t.mistakes.map(q=>`<details class="question"><summary>№${q.number} · ${esc(q.question)}</summary><p>${q.options.filter(o=>o.correct).map(o=>esc(o.text)).join('<br>')}</p></details>`).join('')}</div>`:''}</section>`;return;}
    const q=t.current;const answer=t.answers.at(-1);const multiple=q.options.filter(o=>o.correct).length>1;host.innerHTML=`<div class="training-progress"><span>ВОПРОС ${t.index+1} <i>/ ${t.questions.length}</i></span><span>Верно: ${t.score}</span><div><i style="width:${t.answers.length/t.questions.length*100}%"></i></div></div><article class="training-question"><span class="eyebrow">${multiple?'ВЫБЕРИ ВСЕ ВЕРНЫЕ ВАРИАНТЫ':'ВЫБЕРИ ОДИН ВАРИАНТ'} · №${q.number} В БАНКЕ</span><h2 id="trainQuestionTitle" tabindex="-1">${esc(q.question)}</h2><fieldset class="training-choices"><legend class="sr-only">Варианты ответа</legend>${q.options.map((o,i)=>`<label class="training-choice ${t.checked?(o.correct?'is-correct':t.selected.includes(i)?'is-wrong':''):''}"><input type="${multiple?'checkbox':'radio'}" name="trainingAnswer" value="${i}" data-train-pick="${i}" ${t.selected.includes(i)?'checked':''} ${t.checked?'disabled':''}><b>${String.fromCharCode(65+i)}</b><code>${esc(o.text)}</code>${t.checked&&o.correct?'<span class="choice-result">✓ Верный</span>':t.checked&&t.selected.includes(i)?'<span class="choice-result">× Твой ответ</span>':''}</label>`).join('')}</fieldset><div class="training-feedback" aria-live="polite">${t.checked?`<div class="feedback ${answer.correct?'good':'wrong'}"><strong>${answer.correct?'✓ Верно!':'× Пока неверно'}</strong><p>${answer.correct?'Можно переходить дальше.':'Правильный вариант выделен. Посмотри его перед следующим вопросом.'}</p></div>`:''}</div><div class="training-actions">${t.checked?`<button class="button" data-train-next>${t.index+1===t.questions.length?'Посмотреть результат':'Следующий вопрос'} →</button>`:'<button class="button" data-train-check '+(t.selected.length?'':'disabled')+'>Проверить ответ →</button>'}<button class="button ghost" data-train-reset>Начать заново</button></div></article>`;}

  const SEARCH_INDEX=[...C.lectures.map(x=>({key:x.code,title:x.title,label:'Лекция · '+x.code,body:x.body+' '+x.sections.map(s=>s.title+' '+s.text).join(' ')+' '+x.example,url:routeFor(x)})),...C.practices.map(x=>({key:x.code,title:x.title,label:'Практика · '+x.code,body:x.task+' '+x.steps.join(' '),url:routeFor(x)})),...C.labs.map(x=>({key:x.code,title:x.title,label:'Лабораторная из архива · №'+x.number,body:x.note+' '+x.example+' '+x.steps.join(' '),url:routeFor(x)})),...C.srs.map(x=>({key:x.code,title:x.title,label:'Самостоятельная · '+x.code,body:x.suggestion,url:routeFor(x)})),...C.docs.map(x=>({key:x.id,title:x.title,label:x.original,body:x.refs.join(' ')+' '+x.text,url:routeFor(x)}))];
  function globalSearch(q){q=q.toLowerCase().trim();if(!q){$('#searchResults').innerHTML='<div class="search-hint">Например: «PDO», «M15», «сессии» или «массивы».</div>';return;}const words=q.split(/\s+/);const rows=SEARCH_INDEX.filter(x=>words.every(w=>(x.key+' '+x.title+' '+x.label+' '+x.body).toLowerCase().includes(w))).sort((a,b)=>Number((b.key+' '+b.title).toLowerCase().includes(q))-Number((a.key+' '+a.title).toLowerCase().includes(q)));$('#searchResults').innerHTML=rows.length?rows.slice(0,30).map(x=>{const ix=x.body.toLowerCase().indexOf(words[0]);const start=Math.max(0,ix-45);const snippet=x.body.slice(start,start+155);return `<a class="search-result" href="${x.url}"><small>${esc(x.label)}</small><h3>${esc(x.title)}</h3><p>${start?'…':''}${esc(snippet)}…</p></a>`;}).join('')+(rows.length>30?`<div class="search-hint">Найдено ${rows.length}. Уточни запрос, чтобы сузить результаты.</div>`:''):'<div class="search-hint">Ничего не нашлось. Попробуй другую формулировку.</div>';}
  function openSearch(){const dialog=$('#searchDialog');if(!dialog.open)dialog.showModal();$('#globalSearch').value='';globalSearch('');$('#globalSearch').focus();}
  function closeSearch(){if($('#searchDialog').open)$('#searchDialog').close();}
  function notFound(){return empty('Такой страницы нет','Возможно, адрес скопирован не полностью. Все темы доступны в программе.');}
  let section='home';
  function render(){let parts;try{parts=decodeURIComponent(location.hash.slice(1)).split('/');}catch{parts=['404'];}const [path='home',id]=parts;section={lesson:'course',task:'practice',lab:'practice',labs:'practice',self:'tk',selfstudy:'tk',assessment:'tk',about:'syllabus'}[path]||path||'home';const routes={home,plan:home,calendar,syllabus,tk,pk,ik,course,practice,labs,library,self,assessment,about,saved,playground,lesson:()=>lesson(id),task:()=>task(id),lab:()=>lab(id),material:()=>material(id),selfstudy:()=>selfstudy(id)};const renderer=routes[path||'home'];$('#main').innerHTML=renderer?renderer():notFound();$('#main').dataset.route=[path||'home',id].filter(Boolean).join('/');nav(section);updateProgress();document.title=(ALL_ITEMS.find(x=>(x.code||x.id)===id)?.title||NAV.find(n=>n[0]===section)?.[1]||'Материалы')+' — Веб технологии I · TIFT';document.body.classList.remove('menu-open');$('#menuToggle').setAttribute('aria-expanded','false');syncMenu();if(path==='ik'){examPage=0;renderExam();}if(path==='calendar')renderCalendar();if(path==='course')renderCourse();if(path==='library')renderLibrary();if(path==='assessment')grade();if(path==='playground'){$('#codeEditor').value=playgroundTemplates.counter;runCode();}window.portalMotion?.refresh();window.scrollTo(0,0);if(document.activeElement!==document.body)$('#main').focus({preventScroll:true});}
  window.addEventListener('hashchange',()=>{closeSearch();render();});
  $('.skip').addEventListener('click',event=>{event.preventDefault();$('#main').focus();$('#main').scrollIntoView();});
  $('#main').addEventListener('click',async event=>{const b=event.target.closest('button,a');if(!b)return;
    if(b.dataset.anchor){event.preventDefault();$('#'+b.dataset.anchor)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}
    if(b.hasAttribute('data-exam-mode')){switchExamMode(b.dataset.examMode);return;}
    if(b.hasAttribute('data-train-start')){trainingSession=new window.ExamTrainer(window.EXAM_BANK,Number($('#trainingCount').value));renderTraining();$('#trainQuestionTitle')?.focus({preventScroll:true});return;}
    if(b.hasAttribute('data-train-check')){trainingSession?.check();renderTraining();$('[data-train-next]')?.focus({preventScroll:true});return;}
    if(b.hasAttribute('data-train-next')){trainingSession?.next();renderTraining();($('#trainQuestionTitle')||$('.training-result h2'))?.focus({preventScroll:true});return;}
    if(b.hasAttribute('data-train-reset')){trainingSession=null;renderTraining();$('#trainingCount')?.focus({preventScroll:true});return;}
    if(b.hasAttribute('data-train-retry')){const mistakes=trainingSession.mistakes;trainingSession=new window.ExamTrainer(mistakes,mistakes.length);renderTraining();$('#trainQuestionTitle')?.focus({preventScroll:true});return;}
    if(b.hasAttribute('data-exam-reveal')){examAllAnswers=!examAllAnswers;b.textContent=examAllAnswers?'Скрыть все ответы':'Показать все ответы';renderExam();return;}if(b.hasAttribute('data-exam-page')){examPage+=b.dataset.examPage==='next'?1:-1;renderExam();$('#examSearch').scrollIntoView({block:'start'});return;}if(b.hasAttribute('data-search-open')){openSearch();return;}
    if(b.hasAttribute('data-calendar-filter')){$$('[data-calendar-filter]').forEach(x=>x.classList.toggle('active',x===b));renderCalendar(b.dataset.calendarFilter,$('#calendarSearch').value);return;}
    if(b.hasAttribute('data-save')){const key=b.dataset.save;if(!validKeys.has(key))return;state.saved=isSaved(key)?state.saved.filter(k=>k!==key):[...state.saved,key];save();if(section==='saved'){render();return;}b.classList.toggle('active',isSaved(key));b.setAttribute('aria-pressed',String(isSaved(key)));b.setAttribute('aria-label',isSaved(key)?'Убрать из сохранённого':'Сохранить материал');toast(isSaved(key)?'Сохранено в закладки':'Удалено из закладок');return;}
    if(b.hasAttribute('data-done')){const key=b.dataset.done;if(!validKeys.has(key))return;state.done=isDone(key)?state.done.filter(k=>k!==key):[...state.done,key];save();render();return;}
    if(b.hasAttribute('data-copy')){const text=b.closest('.code-block').querySelector('code').textContent;try{await navigator.clipboard.writeText(text);toast('Код скопирован');}catch{const range=document.createRange();range.selectNodeContents(b.closest('.code-block').querySelector('code'));const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);toast('Код выделен — нажми Ctrl+C');}return;}
    if(b.hasAttribute('data-print')){window.print();return;}
    if(b.hasAttribute('data-export')){download('webstudio-progress.json',JSON.stringify({version:1,course:'Веб технологии I',exported:new Date().toISOString(),...state},null,2),'application/json');return;}
    if(b.hasAttribute('data-course-filter')){$$('#courseFilters [data-course-filter]').forEach(x=>x.classList.toggle('active',x===b));renderCourse(b.dataset.courseFilter,$('#courseSearch').value);return;}
    if(b.hasAttribute('data-lib-filter')){$$('#libraryFilters [data-lib-filter]').forEach(x=>x.classList.toggle('active',x===b));renderLibrary(b.dataset.libFilter,$('#librarySearch').value);return;}
    if(b.hasAttribute('data-template')){$$('[data-template]').forEach(x=>x.classList.toggle('active',x===b));$('#codeEditor').value=playgroundTemplates[b.dataset.template];runCode();return;}
    if(b.hasAttribute('data-run')){runCode();return;}
    if(b.hasAttribute('data-download-code')){download('index.html',$('#codeEditor').value,'text/html;charset=utf-8');return;}
  });
  $('#main').addEventListener('input',event=>{if(event.target.id==='examSearch'){examPage=0;renderExam();}if(event.target.id==='calendarSearch')renderCalendar($('#calendarFilters .active').dataset.calendarFilter,event.target.value);if(event.target.id==='courseSearch')renderCourse($('#courseFilters .active').dataset.courseFilter,event.target.value);if(event.target.id==='librarySearch')renderLibrary($('#libraryFilters .active').dataset.libFilter,event.target.value);if(['tk','pk','ik'].includes(event.target.id))grade();});
  $('#main').addEventListener('change',event=>{if(event.target.hasAttribute('data-train-pick')){trainingSession?.pick(Number(event.target.dataset.trainPick));const check=$('[data-train-check]');if(check)check.disabled=!trainingSession.selected.length;}if(event.target.dataset.check){state.checks[event.target.dataset.check]=event.target.checked;save();}});
  $('#nav').addEventListener('click',event=>{if(event.target.closest('a')?.getAttribute('href')===location.hash){document.body.classList.remove('menu-open');$('#menuToggle').setAttribute('aria-expanded','false');syncMenu();$('#main').focus({preventScroll:true});}});
  $('#openSearch').addEventListener('click',openSearch);$('#closeSearch').addEventListener('click',closeSearch);$('#globalSearch').addEventListener('input',e=>globalSearch(e.target.value));$('#searchResults').addEventListener('click',e=>{if(e.target.closest('a'))closeSearch();});$('#searchDialog').addEventListener('click',e=>{if(e.target===$('#searchDialog'))closeSearch();});
  document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openSearch();}if(event.key==='Escape'){document.body.classList.remove('menu-open');$('#menuToggle').setAttribute('aria-expanded','false');syncMenu();}});
  $('#themeToggle').addEventListener('click',()=>{state.theme=state.theme==='light'?'dark':'light';applyTheme();save();});$('#menuToggle').addEventListener('click',()=>{document.body.classList.toggle('menu-open');$('#menuToggle').setAttribute('aria-expanded',String(document.body.classList.contains('menu-open')));syncMenu();});$('#mobileShade').addEventListener('click',()=>{document.body.classList.remove('menu-open');$('#menuToggle').setAttribute('aria-expanded','false');syncMenu();});
  render();
})();
